package org.fribok.bookkeeping.dataformat;
import org.junit.jupiter.api.Test;import java.sql.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class NormalizedCustomerCreditInvoiceSchemaTest{
 @Test void createsCompleteCreditInvoiceGraphAndKeepsCreditedNumberAsSnapshot()throws Exception{try(Connection c=conn()){new SchemaMigrationRunner(Clock.fixed(Instant.EPOCH,ZoneOffset.UTC)).migrate(c,NormalizedSchemaMigrations.load());long company=company(c);try(var p=c.prepareStatement("INSERT INTO customer_credit_invoice (legacy_id,company_id,number,crediting_invoice_number,tax_free,eu_sale_commodity,eu_sale_third_party_commodity,printed,entered,reminder_count,interest_invoiced,stock_influencing) VALUES (?,?,?,?,FALSE,FALSE,FALSE,FALSE,FALSE,-1,FALSE,FALSE)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,1);p.setLong(2,company);p.setInt(3,2);p.setInt(4,999);p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();long id=k.getLong(1);try(var a=c.prepareStatement("INSERT INTO customer_credit_invoice_address VALUES (?,?, 'invoice',NULL,'','','','','')")){a.setLong(1,id);a.setLong(2,company);a.executeUpdate();}try(var r=c.prepareStatement("INSERT INTO customer_credit_invoice_row (credit_invoice_id,company_id,row_number,quantity) VALUES (?,?,0,-2.5)")){r.setLong(1,id);r.setLong(2,company);r.executeUpdate();}try(var v=c.prepareStatement("INSERT INTO customer_credit_invoice_voucher VALUES (?,0,NULL,'')")){v.setLong(1,id);v.executeUpdate();}try(var v=c.prepareStatement("INSERT INTO customer_credit_invoice_voucher_row VALUES (?,0,NULL,NULL,NULL,NULL,10,NULL,NULL,FALSE,FALSE)")){v.setLong(1,id);v.executeUpdate();}}}c.commit();assertThat(count(c,"customer_credit_invoice")).isEqualTo(1);assertThat(count(c,"customer_credit_invoice_row")).isEqualTo(1);assertThat(count(c,"customer_credit_invoice_voucher_row")).isEqualTo(1);}}
 private static Connection conn()throws Exception{Class.forName("org.hsqldb.jdbcDriver");Connection c=DriverManager.getConnection("jdbc:hsqldb:mem:credit_schema_"+UUID.randomUUID(),"sa","");c.setAutoCommit(false);return c;}private static long company(Connection c)throws Exception{try(var p=c.prepareStatement("INSERT INTO company (legacy_id) VALUES (1)",Statement.RETURN_GENERATED_KEYS)){p.executeUpdate();try(var k=p.getGeneratedKeys()){k.next();return k.getLong(1);}}}private static long count(Connection c,String t)throws Exception{try(var s=c.createStatement();var r=s.executeQuery("SELECT COUNT(*) FROM "+t)){r.next();return r.getLong(1);}}
}
